for match in __import__('re').finditer(r'\]\((\.\./VIFAILBACK/[^)]+)\)',p.read_text()):
 old=match.group(1)
 if not any(c['path']=='docs/THESIS_CODE_MAP.md' and c['before']==old for c in changes):
  change('docs/THESIS_CODE_MAP.md',old,old.replace('../VIFAILBACK/','../implementations/VIFAILBACK/',1))
