parser=argparse.ArgumentParser();parser.add_argument('--apply-after-move-complete',action='store_true');args=parser.parse_args()
byfile={}
for c in changes:byfile.setdefault(c['path'],[]).append(c)
outputs={}
for path,group in byfile.items():
 old=(ROOT/path).read_text();new=old
 for c in group:
  count=new.count(c['before'])
  if count!=1:raise SystemExit(f'Expected exactly one replacement for {path}: count={count}: {c["before"][:100]!r}')
  new=new.replace(c['before'],c['after'],1)
 outputs[path]=(old,new)
plan={'scope':'Current navigation only, apply only after parent MOVE_COMPLETE; no historical evidence or manuscript edits','changes':changes,'files':[{ 'path':p,'before_sha256':hashlib.sha256(o.encode()).hexdigest(),'after_sha256':hashlib.sha256(n.encode()).hexdigest()}for p,(o,n)in outputs.items()]}
if args.apply_after_move_complete:
 for p,(old,new) in outputs.items():
  pre=PHASE/'preimages'/p
  if not pre.exists():raise SystemExit('Missing preserved preimage: '+p)
 for p,(old,new) in outputs.items():(ROOT/p).write_text(new)
 with (PHASE/'NAVIGATION_APPLIED.json').open('x') as f:json.dump(plan,f,indent=2);f.write('\n')
 print(f'Applied navigation changes to {len(outputs)} files')
else:
 with (PHASE/'NAVIGATION_PLAN.json').open('x') as f:json.dump(plan,f,indent=2);f.write('\n')
 print(f'Prepared {len(changes)} bounded replacements in {len(outputs)} files; no navigation files edited')
